#pragma once
#include <cstdint>
#include <cstddef>
#include <utility>
#include <vector>
#include <zlib.h>

namespace crgl {
// Retain only live textures. Compress larger pixel buffers once at upload;
// mip chains are regenerated by GL. Tiny glyph/UI uploads avoid zlib overhead.
class Backup {
public:
    void store(const std::vector<uint8_t>& source) {
        size_ = source.size();
        compressed_ = false;
        if (size_ >= 4096) {
            uLongf n = compressBound(uLong(size_));
            std::vector<uint8_t> packed(n);
            if (compress2(packed.data(), &n, source.data(), uLong(size_), Z_BEST_SPEED) == Z_OK && n < size_) {
                packed.resize(n);
                packed.shrink_to_fit();
                bytes_ = std::move(packed);
                compressed_ = true;
                return;
            }
        }
        bytes_ = source;
    }
    bool unpack(std::vector<uint8_t>& out) const {
        if (!compressed_) { out = bytes_; return true; }
        out.resize(size_);
        uLongf n = uLongf(size_);
        return uncompress(out.data(), &n, bytes_.data(), uLong(bytes_.size())) == Z_OK && n == size_;
    }
private:
    std::vector<uint8_t> bytes_;
    std::size_t size_ = 0;
    bool compressed_ = false;
};
} // namespace crgl
